#!/usr/bin/env node
/**
 * Build each plugin's DATA as its own on-demand browser script (`contributes.data`).
 *
 *   lib/plugins/<name>/<name>.data.generated.js  →  docs/public/playground/lattice-plugin-<name>.js
 *
 * The engine bundle (tools/build-playground.js) aliases lib/plugins/data.generated.js to a stub, so
 * it carries no plugin's data. This script is what carries it instead: it sets
 * `globalThis.__latticePluginData[<name>]`, where lib/plugins/plugin-data.js finds it, and
 * docs/src/lib/render-engine.ts loads it before rendering a deck that uses the plugin (the
 * plugin's `detect`). The KaTeX provider's shape (tools/build-katex-provider.js), for any plugin.
 *
 * Flags: --check (build to a temp file and diff; exit 1 on drift), --silent.
 */
const esbuild = require('esbuild');
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const OUT_DIR = path.join(ROOT, 'docs', 'public', 'playground');
const { DATA_LOADERS } = require('../lib/plugins/data.generated.js');
const check = process.argv.includes('--check');
const silent = process.argv.includes('--silent') || check;

/** The script's file name for a plugin — what render-engine.ts and the asset sync derive too. */
const bundleFile = (name) => `lattice-plugin-${name}.js`;

async function buildOne(name, outFile) {
  const data = path.join(ROOT, 'lib', 'plugins', name, `${name}.data.generated.js`);
  await esbuild.build({
    stdin: {
      contents: `const d = require(${JSON.stringify(data)});\nconst g = globalThis.__latticePluginData || (globalThis.__latticePluginData = {});\ng[${JSON.stringify(name)}] = d;\n`,
      resolveDir: ROOT,
      sourcefile: `plugin-data-${name}.js`,
    },
    bundle: true,
    format: 'iife',
    platform: 'browser',
    target: ['chrome109'],
    minify: true,
    // `inline` keeps each data file's `/*! … */` notice (Tabler's MIT license, for the icons) in the
    // script a browser downloads: the drawings are third-party work, and the notice travels with them.
    legalComments: 'inline',
    banner: { js: `/* Auto-generated by tools/build-plugin-data-bundles.js — DO NOT EDIT. The ${name} plugin's data. */` },
    outfile: outFile,
  });
}

async function main() {
  fs.mkdirSync(OUT_DIR, { recursive: true });
  let stale = 0;
  for (const name of Object.keys(DATA_LOADERS)) {
    const out = path.join(OUT_DIR, bundleFile(name));
    if (check) {
      const tmp = `${out}.check.tmp`;
      await buildOne(name, tmp);
      const same = fs.existsSync(out) && fs.readFileSync(out, 'utf8') === fs.readFileSync(tmp, 'utf8');
      fs.unlinkSync(tmp);
      if (!same) {
        process.stderr.write(`✗ docs/public/playground/${bundleFile(name)} is stale. Run: node tools/build-plugin-data-bundles.js\n`);
        stale++;
      }
      continue;
    }
    await buildOne(name, out);
    if (!silent) process.stdout.write(`[build-plugin-data-bundles] docs/public/playground/${bundleFile(name)}  (${(fs.statSync(out).size / 1024).toFixed(1)} KB)\n`);
  }
  if (stale) process.exit(1);
}

if (require.main === module) {
  main().catch((e) => {
    process.stderr.write(`${e.stack || e}\n`);
    process.exit(1);
  });
}

module.exports = { bundleFile };
